// SLOW: per-key search with no memoisation of visited states (exponential). Generated by mk_wrongs.py.
// Reference: linearizability checker for KV histories (task 168, variant f).
// Per-key Wing-Gong-Lowe search, memoised on (linearized-set, value).
const std = @import("std");

const INF: i64 = std.math.maxInt(i64);
const Kind = enum { get, put, del, cas };

const Op = struct {
    call: i64,
    ret: i64,
    kind: Kind,
    key: i64,
    a: i64 = 0,
    b: i64 = 0,
    res: i64 = 0, // GET value (0 = NIL) / CAS 1=OK 0=FAIL
};

fn byKey(_: void, x: Op, y: Op) bool {
    return x.key < y.key;
}
fn byRet(_: void, x: Op, y: Op) bool {
    return x.ret < y.ret;
}
fn byCall(ops: []const Op, x: usize, y: usize) bool {
    return ops[x].call < ops[y].call;
}

const Memo = struct {
    gpa: std.mem.Allocator,
    width: usize, // words per state (bitset words + 1 value word)
    arena: std.ArrayList(u64) = .empty,
    table: []i64,
    count: usize = 0,

    fn init(gpa: std.mem.Allocator, width: usize) !Memo {
        const t = try gpa.alloc(i64, 1024);
        @memset(t, -1);
        return .{ .gpa = gpa, .width = width, .table = t };
    }
    fn deinit(self: *Memo) void {
        self.arena.deinit(self.gpa);
        self.gpa.free(self.table);
    }
    fn hash(s: []const u64) u64 {
        var h: u64 = 0x9E3779B97F4A7C15;
        for (s) |x| {
            h ^= x;
            h *%= 0xff51afd7ed558ccd;
            h ^= h >> 32;
        }
        return h;
    }
    fn state(self: *Memo, idx: usize) []u64 {
        return self.arena.items[idx * self.width .. (idx + 1) * self.width];
    }
    fn grow(self: *Memo) !void {
        const nt = try self.gpa.alloc(i64, self.table.len * 2);
        @memset(nt, -1);
        self.gpa.free(self.table);
        self.table = nt;
        const mask = nt.len - 1;
        for (0..self.count) |k| {
            var h = hash(self.state(k)) & mask;
            while (nt[h] >= 0) h = (h + 1) & mask;
            nt[h] = @intCast(k);
        }
    }
    /// Returns the index of the state if it was new, null if already seen.
    fn insert(self: *Memo, s: []const u64) !?usize {
        if ((self.count + 1) * 2 > self.table.len) try self.grow();
        const mask = self.table.len - 1;
        var h = hash(s) & mask;
        while (self.table[h] >= 0) {
            h = (h + 1) & mask;
        }
        try self.arena.appendSlice(self.gpa, s);
        self.table[h] = @intCast(self.count);
        self.count += 1;
        return self.count - 1;
    }
};

fn checkKey(gpa: std.mem.Allocator, in_ops: []Op) !bool {
    // completed ops first (by ret), pending after
    var m: usize = 0;
    for (0..in_ops.len) |i| {
        if (in_ops[i].ret != INF) {
            const t = in_ops[m];
            in_ops[m] = in_ops[i];
            in_ops[i] = t;
            m += 1;
        }
    }
    if (m == 0) return true;
    const ops = in_ops;
    std.mem.sort(Op, ops[0..m], {}, byRet);
    const n = ops.len;
    const order = try gpa.alloc(usize, n);
    defer gpa.free(order);
    for (order, 0..) |*o, i| o.* = i;
    std.mem.sort(usize, order, @as([]const Op, ops), byCall);

    const W = (n + 63) / 64;
    var memo = try Memo.init(gpa, W + 1);
    defer memo.deinit();
    var stack: std.ArrayList(usize) = .empty;
    defer stack.deinit(gpa);
    const cur = try gpa.alloc(u64, W + 1);
    defer gpa.free(cur);
    @memset(cur, 0);
    try stack.append(gpa, (try memo.insert(cur)).?);

    while (stack.pop()) |si| {
        @memcpy(cur, memo.state(si));
        var low: usize = n;
        for (0..W) |w| {
            const z = ~cur[w];
            if (z != 0) {
                low = w * 64 + @ctz(z);
                break;
            }
        }
        if (low >= m) return true;
        const minret = ops[low].ret;
        const val: i64 = @bitCast(cur[W]);
        for (order) |i| {
            if (ops[i].call > minret) break;
            const bit = @as(u64, 1) << @intCast(i % 64);
            if (cur[i / 64] & bit != 0) continue;
            const o = ops[i];
            var nv: i64 = undefined;
            switch (o.kind) {
                .get => {
                    if (o.res != val) continue;
                    nv = val;
                },
                .put => nv = o.a,
                .del => nv = 0,
                .cas => {
                    const hit = val != 0 and val == o.a;
                    if (i >= m) {
                        nv = if (hit) o.b else val;
                    } else if (o.res == 1) {
                        if (!hit) continue;
                        nv = o.b;
                    } else {
                        if (hit) continue;
                        nv = val;
                    }
                },
            }
            cur[i / 64] |= bit;
            const saved = cur[W];
            cur[W] = @bitCast(nv);
            const fresh = try memo.insert(cur);
            cur[i / 64] &= ~bit;
            cur[W] = saved;
            if (fresh) |idx| try stack.append(gpa, idx);
        }
    }
    return false;
}

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;
    var rb: [65536]u8 = undefined;
    var fr: std.Io.File.Reader = .init(.stdin(), io, &rb);
    const data = try fr.interface.allocRemaining(gpa, .unlimited);
    defer gpa.free(data);
    var wb: [65536]u8 = undefined;
    var fw: std.Io.File.Writer = .init(.stdout(), io, &wb);
    const w = &fw.interface;

    var it = std.mem.tokenizeAny(u8, data, " \r\n");
    const T = try std.fmt.parseInt(usize, it.next().?, 10);
    for (0..T) |_| {
        const n = try std.fmt.parseInt(usize, it.next().?, 10);
        var ops: std.ArrayList(Op) = .empty;
        defer ops.deinit(gpa);
        for (0..n) |_| {
            const call = try std.fmt.parseInt(i64, it.next().?, 10);
            const rs = it.next().?;
            const pending = std.mem.eql(u8, rs, "?");
            const ret: i64 = if (pending) INF else try std.fmt.parseInt(i64, rs, 10);
            const ks = it.next().?;
            const kind: Kind = switch (ks[0]) {
                'G' => .get,
                'P' => .put,
                'D' => .del,
                else => .cas,
            };
            var o = Op{ .call = call, .ret = ret, .kind = kind, .key = try std.fmt.parseInt(i64, it.next().?, 10) };
            if (kind == .put) o.a = try std.fmt.parseInt(i64, it.next().?, 10);
            if (kind == .cas) {
                o.a = try std.fmt.parseInt(i64, it.next().?, 10);
                o.b = try std.fmt.parseInt(i64, it.next().?, 10);
            }
            if (!pending and kind == .get) {
                const s = it.next().?;
                o.res = if (std.mem.eql(u8, s, "NIL")) 0 else try std.fmt.parseInt(i64, s, 10);
            }
            if (!pending and kind == .cas) {
                o.res = if (std.mem.eql(u8, it.next().?, "OK")) 1 else 0;
            }
            if (pending and kind == .get) continue; // constrains nothing
            try ops.append(gpa, o);
        }
        const items = ops.items;
        std.mem.sort(Op, items, {}, byKey);
        var ok = true;
        var i: usize = 0;
        while (i < items.len and ok) {
            var j = i;
            while (j < items.len and items[j].key == items[i].key) j += 1;
            ok = try checkKey(gpa, items[i..j]);
            i = j;
        }
        try w.writeAll(if (ok) "LINEARIZABLE\n" else "VIOLATION\n");
    }
    try w.flush();
}
